import { describe, expect, it } from 'vitest';
import { InMemoryRepo } from '../src/infra/memoryRepo';
import { StatsEngine } from '../src/engine/stats';

function appt(id: string, clientId: string, serviceId: string, start: string, status: string): void {
  // Helper — we'll use repo.saveAppointment directly
  throw new Error('Use inline saveAppointment');
}

describe('StatsEngine — engine unit tests (seeded repo)', () => {
  it('appointmentsTotal counts all appointments in range regardless of status', () => {
    const repo = new InMemoryRepo(true); // uses seeded data
    const engine = new StatsEngine(repo);

    const start = new Date('2026-01-01T00:00:00.000Z');
    const end = new Date('2027-12-31T00:00:00.000Z');
    const stats = engine.compute(start, end);

    // Seeded repo has 1 appointment (appt-1 with status 'booked')
    expect(stats.appointmentsTotal).toBe(1);
  });

  it('cancellationRate is correctly computed as cancelled/total', () => {
    const repo = new InMemoryRepo(false);
    const engine = new StatsEngine(repo);

    const start = new Date('2099-01-01T00:00:00.000Z');
    const end = new Date('2099-01-02T00:00:00.000Z');

    repo.saveAppointment({
      id: 'a-1', clientId: 'cli-1', serviceId: 'svc-1',
      start: '2099-01-01T10:00:00.000Z',
      end: '2099-01-01T11:00:00.000Z',
      status: 'booked',
    });
    repo.saveAppointment({
      id: 'a-2', clientId: 'cli-2', serviceId: 'svc-1',
      start: '2099-01-01T12:00:00.000Z',
      end: '2099-01-01T13:00:00.000Z',
      status: 'cancelled',
    });

    const stats = engine.compute(start, end);

    expect(stats.appointmentsTotal).toBe(2);
    expect(stats.appointmentsCancelled).toBe(1);
    expect(stats.cancellationRate).toBe(0.5);
  });

  it('cancellationRate is 0 when total is 0', () => {
    const repo = new InMemoryRepo(false);
    const engine = new StatsEngine(repo);

    const stats = engine.compute(
      new Date('2099-01-01T00:00:00.000Z'),
      new Date('2099-01-02T00:00:00.000Z'),
    );

    expect(stats.appointmentsTotal).toBe(0);
    expect(stats.cancellationRate).toBe(0);
  });

  it('sum of booked + completed + cancelled equals total', () => {
    const repo = new InMemoryRepo(false);
    const engine = new StatsEngine(repo);

    const rangeStart = new Date('2099-01-01T00:00:00.000Z');
    const rangeEnd = new Date('2099-01-03T00:00:00.000Z');

    repo.saveAppointment({
      id: 'a-1', clientId: 'cli-1', serviceId: 'svc-1',
      start: '2099-01-01T10:00:00.000Z', end: '2099-01-01T11:00:00.000Z', status: 'booked',
    });
    repo.saveAppointment({
      id: 'a-2', clientId: 'cli-2', serviceId: 'svc-2',
      start: '2099-01-01T12:00:00.000Z', end: '2099-01-01T13:30:00.000Z', status: 'completed',
    });
    repo.saveAppointment({
      id: 'a-3', clientId: 'cli-3', serviceId: 'svc-1',
      start: '2099-01-02T09:00:00.000Z', end: '2099-01-02T10:00:00.000Z', status: 'cancelled',
    });

    const stats = engine.compute(rangeStart, rangeEnd);

    expect(stats.appointmentsBooked + stats.appointmentsCompleted + stats.appointmentsCancelled)
      .toBe(stats.appointmentsTotal);
  });

  it('occupancyRate is correctly computed for booked+completed appointments', () => {
    const repo = new InMemoryRepo(false);
    const engine = new StatsEngine(repo);

    // 1 working day = 540 minutes (9:00-18:00)
    const rangeStart = new Date('2099-01-01T00:00:00.000Z');
    const rangeEnd = new Date('2099-01-02T00:00:00.000Z');

    // Booked appointment: 60 min
    repo.saveAppointment({
      id: 'a-1', clientId: 'cli-1', serviceId: 'svc-1',
      start: '2099-01-01T10:00:00.000Z', end: '2099-01-01T11:00:00.000Z', status: 'booked',
    });
    // Completed appointment: 90 min
    repo.saveAppointment({
      id: 'a-2', clientId: 'cli-2', serviceId: 'svc-2',
      start: '2099-01-01T13:00:00.000Z', end: '2099-01-01T14:30:00.000Z', status: 'completed',
    });
    // Cancelled: 120 min — should NOT count toward occupancy
    repo.saveAppointment({
      id: 'a-3', clientId: 'cli-3', serviceId: 'svc-3',
      start: '2099-01-01T09:00:00.000Z', end: '2099-01-01T11:00:00.000Z', status: 'cancelled',
    });

    const stats = engine.compute(rangeStart, rangeEnd);

    // 150 min used / 540 min available = 0.2778
    expect(stats.occupancyRate).toBeCloseTo(150 / 540, 4);
  });

  it('top services by bookings returns top 5 sorted descending with stable tie-break by id', () => {
    const repo = new InMemoryRepo(false);
    const engine = new StatsEngine(repo);

    const rangeStart = new Date('2099-01-01T00:00:00.000Z');
    const rangeEnd = new Date('2099-01-02T00:00:00.000Z');

    repo.saveAppointment({
      id: 'a-1', clientId: 'cli-1', serviceId: 'svc-b',
      start: '2099-01-01T10:00:00.000Z', end: '2099-01-01T11:00:00.000Z', status: 'booked',
    });
    repo.saveAppointment({
      id: 'a-2', clientId: 'cli-2', serviceId: 'svc-a',
      start: '2099-01-01T12:00:00.000Z', end: '2099-01-01T13:00:00.000Z', status: 'booked',
    });
    repo.saveAppointment({
      id: 'a-3', clientId: 'cli-3', serviceId: 'svc-a',
      start: '2099-01-01T14:00:00.000Z', end: '2099-01-01T15:00:00.000Z', status: 'completed',
    });

    const stats = engine.compute(rangeStart, rangeEnd);

    // svc-a: 1 booked, svc-b: 1 booked — tie, break by id ascending
    expect(stats.topServicesByBookings).toEqual([
      { serviceId: 'svc-a', count: 1 },
      { serviceId: 'svc-b', count: 1 },
    ]);
  });

  it('top clients by visits counts booked + completed only', () => {
    const repo = new InMemoryRepo(false);
    const engine = new StatsEngine(repo);

    const rangeStart = new Date('2099-01-01T00:00:00.000Z');
    const rangeEnd = new Date('2099-01-03T00:00:00.000Z');

    repo.saveAppointment({
      id: 'a-1', clientId: 'cli-1', serviceId: 'svc-1',
      start: '2099-01-01T10:00:00.000Z', end: '2099-01-01T11:00:00.000Z', status: 'booked',
    });
    repo.saveAppointment({
      id: 'a-2', clientId: 'cli-1', serviceId: 'svc-2',
      start: '2099-01-02T10:00:00.000Z', end: '2099-01-02T11:00:00.000Z', status: 'cancelled',
    });
    repo.saveAppointment({
      id: 'a-3', clientId: 'cli-2', serviceId: 'svc-1',
      start: '2099-01-01T12:00:00.000Z', end: '2099-01-01T13:00:00.000Z', status: 'completed',
    });

    const stats = engine.compute(rangeStart, rangeEnd);

    // cli-1: 1 visit (booked), cli-2: 1 visit (completed) — tie, break by id
    expect(stats.topClientsByVisits).toEqual([
      { clientId: 'cli-1', count: 1 },
      { clientId: 'cli-2', count: 1 },
    ]);
  });
});

import { describe, expect, it } from 'vitest';
import { InMemoryRepo } from '../src/infra/memoryRepo';
import { StatsEngine } from '../src/engine/stats';

/**
 * E2E test: one week with mixed statuses.
 * Expected: appointmentsTotal=10, cancellationRate=0.2, ordered tops.
 */
describe('StatsEngine — e2e: mixed week', () => {
  it('computes stats over a week with 10 appointments (total=10, cancellationRate=0.2)', () => {
    const repo = new InMemoryRepo(false);

    const engine = new StatsEngine(repo);

    const rangeStart = new Date('2099-01-04T00:00:00.000Z'); // Monday
    const rangeEnd = new Date('2099-01-11T00:00:00.000Z');   // next Monday (exclusive)

    // 10 appointments across the week:
    //   booked: 4, completed: 4, cancelled: 2 → total=10, cancellationRate=0.2
    // Services: svc-bano(4), svc-corte(4), svc-spa(2)
    // Clients: cli-ana(5), cli-bob(5)

    // Tuesday: 2 appointments
    repo.saveAppointment({
      id: 'a-1', clientId: 'cli-ana', serviceId: 'svc-bano',
      start: '2099-01-05T10:00:00.000Z', end: '2099-01-05T11:00:00.000Z', status: 'booked',
    });
    repo.saveAppointment({
      id: 'a-2', clientId: 'cli-bob', serviceId: 'svc-bano',
      start: '2099-01-05T12:00:00.000Z', end: '2099-01-05T13:00:00.000Z', status: 'completed',
    });

    // Wednesday: 3 appointments
    repo.saveAppointment({
      id: 'a-3', clientId: 'cli-ana', serviceId: 'svc-corte',
      start: '2099-01-06T09:00:00.000Z', end: '2099-01-06T10:30:00.000Z', status: 'booked',
    });
    repo.saveAppointment({
      id: 'a-4', clientId: 'cli-bob', serviceId: 'svc-spa',
      start: '2099-01-06T13:00:00.000Z', end: '2099-01-06T15:00:00.000Z', status: 'completed',
    });
    repo.saveAppointment({
      id: 'a-5', clientId: 'cli-bob', serviceId: 'svc-bano',
      start: '2099-01-06T16:00:00.000Z', end: '2099-01-06T17:00:00.000Z', status: 'booked',
    });

    // Thursday: 3 appointments
    repo.saveAppointment({
      id: 'a-6', clientId: 'cli-ana', serviceId: 'svc-corte',
      start: '2099-01-07T10:00:00.000Z', end: '2099-01-07T11:30:00.000Z', status: 'completed',
    });
    repo.saveAppointment({
      id: 'a-7', clientId: 'cli-ana', serviceId: 'svc-bano',
      start: '2099-01-07T13:00:00.000Z', end: '2099-01-07T14:00:00.000Z', status: 'cancelled',
    });
    repo.saveAppointment({
      id: 'a-8', clientId: 'cli-bob', serviceId: 'svc-corte',
      start: '2099-01-07T15:00:00.000Z', end: '2099-01-07T16:30:00.000Z', status: 'booked',
    });

    // Friday: 2 appointments
    repo.saveAppointment({
      id: 'a-9', clientId: 'cli-bob', serviceId: 'svc-spa',
      start: '2099-01-08T10:00:00.000Z', end: '2099-01-08T12:00:00.000Z', status: 'booked',
    });
    repo.saveAppointment({
      id: 'a-10', clientId: 'cli-bob', serviceId: 'svc-corte',
      start: '2099-01-08T13:00:00.000Z', end: '2099-01-08T14:30:00.000Z', status: 'cancelled',
    });

    const stats = engine.compute(rangeStart, rangeEnd);

    // --- Volume checks ---
    expect(stats.appointmentsTotal).toBe(10);
    expect(stats.appointmentsBooked).toBe(4);
    expect(stats.appointmentsCompleted).toBe(4);
    expect(stats.appointmentsCancelled).toBe(2);
    expect(stats.cancellationRate).toBe(0.2);

    // --- Top services by bookings (only booked status) ---
    // svc-bano: 2 booked (a-1, a-5)
    // svc-corte: 2 booked (a-3, a-8)
    // svc-spa: 1 booked (a-9)
    expect(stats.topServicesByBookings).toEqual([
      { serviceId: 'svc-bano', count: 2 },
      { serviceId: 'svc-corte', count: 2 },
      { serviceId: 'svc-spa', count: 1 },
    ]);

    // --- Top services by cancellations ---
    // svc-bano: 1 (a-7)
    // svc-corte: 1 (a-10)
    expect(stats.topServicesByCancellations).toEqual([
      { serviceId: 'svc-bano', count: 1 },
      { serviceId: 'svc-corte', count: 1 },
    ]);

    // --- Top clients by visits (booked + completed) ---
    // cli-ana: 5 visits (a-1 booked, a-3 booked, a-6 completed, a-2 completed, a-5 booked)
    // Wait, let me recount:
    // cli-ana: a-1(booked), a-3(booked), a-6(completed) = 3 visits
    // cli-bob: a-2(completed), a-5(booked), a-4(completed), a-8(booked), a-9(booked) = 5 visits
    expect(stats.topClientsByVisits).toEqual([
      { clientId: 'cli-bob', count: 5 },
      { clientId: 'cli-ana', count: 3 },
    ]);
  });
});

import { describe, expect, it } from 'vitest';
import { InMemoryRepo } from '../src/infra/memoryRepo';
import { StatsEngine } from '../src/engine/stats';

describe('StatsEngine — edge cases', () => {
  it('empty range: no appointments, all rates are 0, tops are empty', () => {
    const repo = new InMemoryRepo(false);
    const engine = new StatsEngine(repo);

    const stats = engine.compute(
      new Date('2099-01-01T00:00:00.000Z'),
      new Date('2099-01-02T00:00:00.000Z'),
    );

    expect(stats.appointmentsTotal).toBe(0);
    expect(stats.appointmentsBooked).toBe(0);
    expect(stats.appointmentsCompleted).toBe(0);
    expect(stats.appointmentsCancelled).toBe(0);
    expect(stats.cancellationRate).toBe(0);
    expect(stats.occupancyRate).toBe(0);
    expect(stats.topServicesByBookings).toEqual([]);
    expect(stats.topServicesByCancellations).toEqual([]);
    expect(stats.topClientsByVisits).toEqual([]);
  });

  it('all cancelled: cancellationRate=1, occupancy=0', () => {
    const repo = new InMemoryRepo(false);
    const engine = new StatsEngine(repo);

    const rangeStart = new Date('2099-01-01T00:00:00.000Z');
    const rangeEnd = new Date('2099-01-02T00:00:00.000Z');

    repo.saveAppointment({
      id: 'a-1', clientId: 'cli-1', serviceId: 'svc-1',
      start: '2099-01-01T10:00:00.000Z', end: '2099-01-01T11:00:00.000Z', status: 'cancelled',
    });
    repo.saveAppointment({
      id: 'a-2', clientId: 'cli-2', serviceId: 'svc-2',
      start: '2099-01-01T13:00:00.000Z', end: '2099-01-01T14:00:00.000Z', status: 'cancelled',
    });

    const stats = engine.compute(rangeStart, rangeEnd);

    expect(stats.appointmentsTotal).toBe(2);
    expect(stats.appointmentsCancelled).toBe(2);
    expect(stats.cancellationRate).toBe(1);
    expect(stats.occupancyRate).toBe(0);
    expect(stats.topServicesByBookings).toEqual([]);
  });

  it('occupancy 100%: booked appointments fill entire working day', () => {
    const repo = new InMemoryRepo(false);
    const engine = new StatsEngine(repo);

    const rangeStart = new Date('2099-01-01T00:00:00.000Z');
    const rangeEnd = new Date('2099-01-02T00:00:00.000Z');

    // Booked 9h (540 min) = full working day
    repo.saveAppointment({
      id: 'a-1', clientId: 'cli-1', serviceId: 'svc-1',
      start: '2099-01-01T09:00:00.000Z', end: '2099-01-01T18:00:00.000Z', status: 'booked',
    });

    const stats = engine.compute(rangeStart, rangeEnd);

    // 540 min used / 540 min available = 1.0
    expect(stats.occupancyRate).toBe(1);
  });

  it('ties: stable sort by id ascending for top services by bookings', () => {
    const repo = new InMemoryRepo(false);
    const engine = new StatsEngine(repo);

    const rangeStart = new Date('2099-01-01T00:00:00.000Z');
    const rangeEnd = new Date('2099-01-02T00:00:00.000Z');

    // 3 services with same booking count
    repo.saveAppointment({
      id: 'a-1', clientId: 'cli-1', serviceId: 'svc-c',
      start: '2099-01-01T10:00:00.000Z', end: '2099-01-01T11:00:00.000Z', status: 'booked',
    });
    repo.saveAppointment({
      id: 'a-2', clientId: 'cli-2', serviceId: 'svc-a',
      start: '2099-01-01T12:00:00.000Z', end: '2099-01-01T13:00:00.000Z', status: 'booked',
    });
    repo.saveAppointment({
      id: 'a-3', clientId: 'cli-3', serviceId: 'svc-b',
      start: '2099-01-01T14:00:00.000Z', end: '2099-01-01T15:00:00.000Z', status: 'booked',
    });

    const stats = engine.compute(rangeStart, rangeEnd);

    // All have count=1, stable sort by id ascending: a < b < c
    expect(stats.topServicesByBookings).toEqual([
      { serviceId: 'svc-a', count: 1 },
      { serviceId: 'svc-b', count: 1 },
      { serviceId: 'svc-c', count: 1 },
    ]);
  });

  it('ties: stable sort by id ascending for top clients by visits', () => {
    const repo = new InMemoryRepo(false);
    const engine = new StatsEngine(repo);

    const rangeStart = new Date('2099-01-01T00:00:00.000Z');
    const rangeEnd = new Date('2099-01-03T00:00:00.000Z');

    // 3 clients with same visit count
    repo.saveAppointment({
      id: 'a-1', clientId: 'cli-c', serviceId: 'svc-1',
      start: '2099-01-01T10:00:00.000Z', end: '2099-01-01T11:00:00.000Z', status: 'booked',
    });
    repo.saveAppointment({
      id: 'a-2', clientId: 'cli-a', serviceId: 'svc-1',
      start: '2099-01-02T10:00:00.000Z', end: '2099-01-02T11:00:00.000Z', status: 'completed',
    });
    repo.saveAppointment({
      id: 'a-3', clientId: 'cli-b', serviceId: 'svc-2',
      start: '2099-01-01T12:00:00.000Z', end: '2099-01-01T13:00:00.000Z', status: 'completed',
    });

    const stats = engine.compute(rangeStart, rangeEnd);

    // All have count=1, stable sort by id ascending: a < b < c
    expect(stats.topClientsByVisits).toEqual([
      { clientId: 'cli-a', count: 1 },
      { clientId: 'cli-b', count: 1 },
      { clientId: 'cli-c', count: 1 },
    ]);
  });

  it('range boundary: start inclusive, end exclusive', () => {
    const repo = new InMemoryRepo(false);
    const engine = new StatsEngine(repo);

    const rangeStart = new Date('2099-01-01T00:00:00.000Z');
    const rangeEnd = new Date('2099-01-03T00:00:00.000Z');

    // Appointment exactly at rangeStart → included
    repo.saveAppointment({
      id: 'a-start', clientId: 'cli-1', serviceId: 'svc-1',
      start: '2099-01-01T00:00:00.000Z', end: '2099-01-01T01:00:00.000Z', status: 'booked',
    });

    // Appointment exactly at rangeEnd → excluded
    repo.saveAppointment({
      id: 'a-end', clientId: 'cli-1', serviceId: 'svc-1',
      start: '2099-01-03T00:00:00.000Z', end: '2099-01-03T01:00:00.000Z', status: 'booked',
    });

    // Appointment in middle → included
    repo.saveAppointment({
      id: 'a-mid', clientId: 'cli-1', serviceId: 'svc-1',
      start: '2099-01-02T10:00:00.000Z', end: '2099-01-02T11:00:00.000Z', status: 'booked',
    });

    const stats = engine.compute(rangeStart, rangeEnd);

    expect(stats.appointmentsTotal).toBe(2);
    expect(stats.appointmentsBooked).toBe(2);
  });
});

